// AUTO-GENERATED from src/core/tools/*/description.txt by scripts/generate-tool-descriptions.mjs. Do not edit by hand.

/** 工具目录名 → 该工具的完整描述（LLM 可见）。缺失的工具退回其代码内的 fallback。 */
export const TOOL_DESCRIPTIONS: Record<string, string> = {
	"ask-user-question": "Ask the user one or more multiple-choice questions during execution, then block until they answer. Use this to gather preferences or requirements, clarify ambiguous instructions, get a decision on an implementation choice, or offer the user a direction to take.\n\nUsage notes:\n- Prefer asking over guessing when a choice would meaningfully change what you build and you cannot resolve it from the request, the code, or sensible defaults. Do NOT use it for choices with an obvious default or facts you can verify yourself.\n- Put several related questions in ONE call (questions supports 1-4). Do not call this tool repeatedly in a row for things you could ask together.\n- Each question needs 2-4 options. Do NOT add an \"Other\" option yourself — the user can always type free text via an automatic \"Other\" input.\n- To recommend an option, add a badge like [\"推荐\"] (or \"Recommended\") to it and make it the first option. You may add other short badges to signal trade-offs (e.g. \"更快\", \"成本低\"). Badges are display-only guidance.\n- Set multiSelect: true only when the user may legitimately pick more than one option.\n- Keep `header` to a few characters — it is shown as a small chip.\n\nAfter the user answers, you receive their selections (free-text answers included) and continue. If the user cancels, you are told they declined; proceed without their input.",
	"bash": "Execute a bash command in the current working directory. Returns stdout and stderr. Output is truncated to last 2000 lines or 50KB (whichever is hit first). If truncated, full output is saved to a temp file. Optionally provide a timeout in seconds.\n\n# Foreground vs background (CRITICAL)\n\nDefault is FOREGROUND: the agent is BLOCKED until the command exits (or until the soft wait, then auto-promote — see Modes).\n\nNEVER run a process that does not exit on its own in the foreground without `run_in_background: true`.\n\nMUST set `run_in_background: true` for anything that keeps the console open / runs until killed, including:\n- Dev servers: npm/pnpm/yarn/bun run dev|start, vite, next dev, nuxt, webpack-dev-server\n- Watchers: *--watch*, nodemon, vitest --watch, jest --watch\n- Containers: docker compose up (without -d), docker run (without -d)\n- Make/scripts that serve: make dev, make serve, rails s, flask run, uvicorn (no oneshot)\n- Tunnels / REPL / follow: ssh -N, tail -f, python -i\n\nDecision:\n- Will this process exit on its own within about a minute? → foreground (optional hard `timeout`)\n- Will it keep running until killed? → `run_in_background: true`\n- Unsure? → `run_in_background: true`\n\nDo NOT use shell `&`, `nohup`, or manual disown; use `run_in_background`.\nDo NOT poll with long `sleep` while waiting on a foreground server — that hangs the agent.\n\n# Modes\n\n1. `run_in_background: true` — starts immediately as a background task; returns task ID. Use `task_output` / `task_stop`. When the command finishes you receive a `<task-notification>`. Ignores timeout.\n2. `timeout: N` — foreground with hard kill after N seconds (bounded work: builds, one-shot tests).\n3. Neither set — foreground soft wait (default 45s). If still running, auto-promoted to a background task (same as background after the wait). Quick commands still return inline when they exit before the soft wait.\n\nDo NOT use `run_in_background` for quick one-shot commands — the result arrives faster inline.\n\nIMPORTANT: NEVER use bash for operations that have dedicated tools. Use the right tool:\n- File reading: ALWAYS use `read` (NEVER cat, head, tail, less, more)\n- File editing: ALWAYS use `edit` (NEVER sed, awk, perl -i)\n- File writing: ALWAYS use `write` (NEVER echo >, cat <<EOF, tee)\n- File search by name: ALWAYS use `find` (NEVER bash find, fd, locate)\n- File content search: ALWAYS use `grep` (NEVER bash grep, rg, ag, ack)\n- Directory listing: ALWAYS use `ls` or `dir_tree` (NEVER bash ls, tree)\n- PDF text extraction: ALWAYS use `extract_text_from_pdf` (NEVER pdftotext, pdf2txt, pdfinfo)\n- Image text extraction: ALWAYS use `extract_text_from_img` (NEVER tesseract, ocrmypdf)\n- Skill invocation: ALWAYS use `invoke_skill` (NEVER bash find/locate/mdfind to search for skill files)\n\nUse bash ONLY for: running scripts, package managers (npm, pip, cargo, etc.), git commands, compilers, interpreters, complex piping, or commands with no dedicated tool equivalent.\n\n# Skill / Scene Directory Protection\n\nSkill and scene directories are READ-ONLY. NEVER write output files, temp files, logs, or any generated content into skill or scene directories.\n\nProtected paths (NEVER write here):\n- ~/.vetta/agent/skills/ and its subdirectories\n- ~/.vetta/skills/ and its subdirectories\n- ~/.vetta/scenes/ and its subdirectories\n- .vetta/skills/ under the current project\n\nWhen a skill or scene needs to produce output files (e.g. generated PDFs, images, reports), ALWAYS write them to the user's working directory (cwd) or a subdirectory thereof. For example, write to `./output.pdf` instead of placing the file inside the skill folder.\n\n# Git Safety Protocol\n\nWhen running git commands, follow these rules strictly:\n- NEVER run destructive git commands without explicit user request:\n  - `git reset --hard` - destroys uncommitted changes\n  - `git push --force` / `git push -f` - can overwrite remote history\n  - `git checkout .` / `git restore .` - discards all local changes\n  - `git clean -fd` - deletes untracked files permanently\n  - `git branch -D` - force-deletes a branch\n  - `git stash drop` - permanently discards stashed changes\n- NEVER skip hooks: do NOT use `--no-verify` or `--no-gpg-sign` unless user explicitly asks\n- NEVER use `git add -A` or `git add .` - these can stage unrelated files. ALWAYS add specific files by path\n- NEVER amend commits unless user explicitly requests it - amending can destroy the previous commit\n- Before any destructive operation, consider if there is a safer alternative\n\n注意：对用户可见的输出文案禁止硬编码中文，统一走 i18n。",
	"current-time": "Get the current system date and time. Returns the time in YYYY-MM-DD HH:mm:ss format.\n\nALWAYS use this tool as your FIRST choice when you need to know the current date or time — for example to add timestamps, check deadlines, or answer time-related questions. Do NOT use bash \"date\" or other shell commands to get the current time. Only fall back to bash if this tool cannot fulfill the specific requirement (e.g., timezone conversion, date arithmetic).",
	"doc-to-pdf": "Convert a document file (.doc, .docx) to PDF format.\n\nUses Microsoft Office or WPS Office installed on the system to perform high-fidelity conversion. Detection priority: Microsoft Office first, then WPS Office. If neither is available, returns an error with installation guidance.\n\nSupported input formats: .doc, .docx\nOutput: PDF file (same name, .pdf extension, or custom output path)",
	"easy-use-vetta-app": "Request Vetta Desktop UI assistance before using app-control actions.\n\nUse this tool when you want Vetta Desktop to show the user a contextual UI for an application action, such as confirming navigation, choosing appearance settings, previewing a proposed change, or filling action-specific fields.\n\nThis tool is generic. Do not treat it as a yes/no prompt only. Provide the action id, your intent, the proposed action input, and a UI plan. The host may return approval, rejection, edited input, selected values, or other structured output.\n\nAfter the tool returns, follow the returned status and output. If it returns allowedActions, only proceed with action calls that match those returned action ids and inputs.",
	"edit": "Edit a file surgically. Two modes — anchor mode (preferred) and exact-text mode.\n\nANCHOR MODE (preferred): pass `edits`, an array of { anchor, end_anchor?, new_text, insert_after? }.\n- Anchors are the `line:hash` prefixes in read/grep/edit output (e.g. `42:h7x2` from a read line `42:h7x2→const x = 1;`). Copy them VERBATIM — never fabricate, compute, or guess an anchor; only tool output is a valid source.\n- The anchor is the WHOLE `line:hash` prefix. The line number is part of the anchor, NOT display decoration — passing the hash alone (e.g. `h7x2`) is wrong.\n- One edit replaces the anchor line (or the inclusive range anchor..end_anchor) with new_text. `end_anchor` is INCLUDED: if its line contains a closing brace, bracket, or JSX tag that should remain, reproduce that closer in new_text. Empty new_text deletes the range. insert_after: true inserts new_text after the anchor line instead.\n- No need to reproduce the old text — the anchor is the identity. This avoids whitespace/punctuation mismatch failures entirely.\n- The batch is ATOMIC: if any anchor is stale (file changed there), ALL edits are rejected and the error returns fresh anchors around each failed target — retry the full batch with those, without re-reading the file.\n- Line numbers in anchors are hints: if content merely moved a few lines, the edit finds it again automatically.\n- After a successful edit, the result includes fresh anchors around each change — use them to continue editing without re-reading.\n\nEXACT-TEXT MODE (fallback): pass oldText/newText. oldText must match exactly (including whitespace) and be unique in the file. Use only when you have no anchors for the target region.\n\nWhen to use `edit` vs `write`:\n- Use `edit` for modifying specific parts of an existing file (preferred for most changes)\n- Use `write` ONLY for creating new files or complete rewrites where most content changes\n- NEVER use bash commands (sed, awk, perl -i) for file editing — always use this tool\n\nYou MUST read a file before editing it. Anchor mode enforces this mechanically — anchors only come from tool output.",
	"extract-text-from-img": "Extract text from an image (PNG / JPG / WebP / BMP / GIF) using Vetta Desktop's local PP-OCRv5 runner.\n\nRuns entirely locally — no network calls. Designed for screenshots, scanned single pages, photographed documents.\n\nThis tool calls the Vetta Desktop executable in command-line OCR mode. Vetta Desktop must be installed, or VETTA_DESKTOP_EXE must point to the desktop executable.\n\nInput\n  - input: path to an image file. Supported extensions: .png .jpg .jpeg .webp .bmp .gif\n  - output (optional): path to write the structured JSON. Default: <input>.ocr.json next to the source.\n  - max_chars (optional): truncate the returned text. Default 8000. The full text is always written to the output JSON.\n\nOutput (text returned to the agent)\n  Recognized text followed by a metadata footer:\n  - confidence (0..100, rough mapping of CTC logit, useful for relative comparison)\n  - duration_ms, engine\n  - output: absolute path to the full JSON\n\nLimitations\n  - Designed for printed text (Chinese + English). Handwriting, seals, and stylized fonts will be poor.\n  - Tables are flattened into lines (column structure is lost).\n  - Confidence is a coarse signal — don't gate decisions on a hard threshold.\n\nWhen to use\n  - You have a single image you need text from (screenshot of a document, scanned receipt, photo of a sign).\n\nWhen NOT to use\n  - You need a VISUAL judgment on the image — presence/absence of seals (盖章/印章), signatures, handwriting, logos, layout, color. OCR returns text only; call `read` on the image directly so a vision-capable model can look at it.\n  - The image is a multi-page PDF — use `extract_text_from_pdf` (text) or `render_pdf_page` (visual).\n  - You need layout / coordinates / table structure.",
	"extract-text-from-pdf": "Extract text from a PDF (scanned or born-digital) using Vetta Desktop's bundled OCR runner.\n\nPages with an embedded text layer are read directly (near-perfect accuracy, milliseconds per page). Pages without a usable text layer fall through to PP-OCRv5 (Chinese + English, ~1-2s per page on a modern machine). All work runs locally — no network calls.\n\nThis tool calls the Vetta Desktop executable in command-line OCR mode. Vetta Desktop must be installed, or VETTA_DESKTOP_EXE must point to the desktop executable.\n\nInput\n  - input: path to the PDF file\n  - output (optional): path to write the full structured JSON result. Default: <input>.ocr.json next to the source.\n  - pages (optional): \"all\" | \"N\" | \"N-M\". Default \"all\". For PDFs with many pages, prefer a range so you don't burn time on parts you don't need.\n  - dpi (optional): render DPI for OCR fallback. Default 150. Lower values are faster and use less memory; higher values help small print. If OCR hits OOM, retry with a smaller DPI. When omitted, this tool may automatically lower DPI for oversized PDF pages so rendered images stay within a safer pixel size.\n  - max_chars (optional): truncate the returned text at this many characters. Default 8000. The full text is always written to the output JSON.\n  - prefer_text_layer (optional): try the embedded text layer first. Default true.\n\nOutput (text returned to the agent)\n  Concatenated page text with `=== Page N ===` separators, truncated to max_chars. Followed by a metadata footer:\n  - total_pages, processed_pages, text_layer_pages, ocr_pages, duration_ms\n  - output: absolute path to the full JSON document\n\nLimitations\n  - Does not preserve table structure (rows/columns are flattened into lines).\n  - Does not recognize handwriting, official seals/stamps, signatures, logos, or formula notation. OCR returns text only — it CANNOT tell you whether a stamp/signature is present, what color it is, or where it sits on the page.\n  - Confidence numbers in the JSON are 0..100 but reflect a coarse mapping of CTC logits — use them for relative comparison between pages, not as a hard quality threshold.\n\nWhen to use\n  - You need the textual content of a scanned PDF or one whose text layer you suspect is unreliable.\n  - You need a structured per-page JSON to feed downstream code (use the output file).\n\nWhen NOT to use\n  - You need a VISUAL judgment on the page — presence/absence of seals (盖章/印章/公章), signatures, handwriting, logos, layout, watermarks, figures, color. Use `render_pdf_page` to produce a PNG, then `read` that PNG. Do NOT call this tool hoping the text output will reveal a stamp — it will not.\n  - You want to manipulate the PDF itself (merge/split/rotate/watermark/fill form). Use `invoke_skill(name=\"pdf\")`.\n  - The PDF clearly has a clean text layer and you only want raw text — `read` plus a PDF-text-extracting tool would be cheaper.\n  - You need layout fidelity (PP-Structure / table extraction is out of scope here).",
	"find": "Search for files by glob pattern. Returns matching file paths relative to the search directory. Respects .gitignore. Output is truncated to 1000 results or 30KB (whichever is hit first).\n\nALWAYS use this tool for file name search. NEVER use bash find, fd, or locate — this tool is faster, respects .gitignore, and has consistent output formatting.\n\nWhen to use `find` vs other tools:\n- Use `find` to search for files BY NAME or glob pattern (e.g., \"*.ts\", \"config.*\", \"**/*.test.js\")\n- Use `grep` to search for text/patterns INSIDE file contents\n- Use `dir_tree` to visualize directory structure with hierarchy\n- Use `ls` to list immediate contents of a single directory",
	"glob": "Fast file and directory pattern matching by glob pattern. Returns matching paths relative to the search directory. Respects .gitignore. Output is truncated to 100 results or 30KB (whichever is hit first).\n\nALWAYS use this tool for file or directory name glob searches. NEVER use bash find, fd, rg --files, or locate for this task - this tool respects .gitignore and has consistent output formatting.\n\nWhen to use `glob` vs other tools:\n- Use `glob` to find files or directories BY NAME or wildcard pattern (e.g., \"**/*.ts\", \"src/**/*.spec.ts\", \"src/**\", \"package*.json\")\n- Use `grep` to search for text/patterns INSIDE file contents\n- Use `dir_tree` to visualize directory structure with hierarchy\n- Use `ls` to list immediate contents of a single directory",
	"grep": "Search file contents for a pattern. Returns matching lines as `path:line:hash: content` — the `line:hash` part is an anchor usable directly in the `edit` tool's anchor mode. Respects .gitignore. Output is truncated to 100 matches or 30KB (whichever is hit first). Long lines are truncated to 2000 chars.\n\nALWAYS use this tool for content search. NEVER use bash grep, rg, ag, or ack — this tool is faster, respects .gitignore, and provides better formatted output.\n\nWhen to use `grep` vs other tools:\n- Use `grep` to search for text/patterns INSIDE files (function names, variable references, error messages, etc.)\n- Use `find` to search for files BY NAME or glob pattern (e.g., \"*.ts\", \"config.*\")\n- Use `dir_tree` to get a high-level overview of directory structure\n- For complex multi-round searches that may need several attempts, consider delegating to a subagent",
	"html-to-pdf": "Convert an HTML file to a PDF using Vetta Desktop's bundled Electron Chromium renderer.\n\nThis tool calls the Vetta Desktop executable in command-line PDF mode. Vetta Desktop must be installed, or VETTA_DESKTOP_EXE must point to the desktop executable.\n\nInput: HTML file path and required output PDF path\nOutput: PDF file path",
	"im-send-attachment": "Send a local file as an attachment to the current IM conversation (e.g. WeChat).\n\nUse when you have produced an artifact the user should receive as a file or image rather than as a code block — for example a generated PDF, a screenshot, a packaged zip, or an image you composed. Each call delivers exactly one attachment and counts as one outbound message against the per-peer quota.\n\nParameters:\n- path: Absolute path to the local file to send. Must exist and be readable.\n- kind: \"image\" for jpg/png/gif/webp images that should be rendered inline by the IM client; \"file\" for everything else (pdf, zip, generic documents).\n- caption: Optional short text to accompany the attachment. Some platforms render it as a follow-up text message; treat it as non-essential.\n\nOn success, returns a `messageId` and the kind that was sent. On quota exhaustion the tool returns an error containing `quota_exhausted` — when this happens, do NOT retry in the same turn; either tell the user to reply (which resets the window) or finish the turn without the attachment. Other failures (file not found, peer unreachable, transport error) are also returned as errors — surface them to the user verbatim.\n\nThis tool is only registered when the agent was started with `--mode rpc --enable-host-bridge`.",
	"invoke-skill": "Invoke a skill by name. Skills are specialized instruction sets for specific tasks (e.g., processing PDF files, handling DOCX documents, data analysis).\n\nWhen the user's request matches a skill listed in <available_skills>, you MUST call this tool BEFORE attempting to handle the task yourself. This is a BLOCKING REQUIREMENT — do not try to accomplish the task manually when a matching skill exists.\n\nThe tool reads the skill's instruction file, strips metadata, and returns the full skill content. Follow the returned instructions to complete the task.\n\nNEVER use bash commands like find, locate, or mdfind to search for skill files. Always use this tool with the exact skill name from <available_skills>.",
	"kb-filter-by-tags": "Filter knowledge base wiki pages by their tags, using set algebra.\n\n- all: intersection — page must contain ALL of these tags (AND)\n- any: union — page must contain AT LEAST ONE of these tags (OR)\n- none: complement — page must contain NONE of these tags (NOT), relative to the whole base\n\nThe three clauses combine with AND. An omitted/empty clause adds no constraint; an empty query returns all live pages. Orphaned pages are excluded. Returns each matched page's id, absolute file path, title and summary so you can drill down. Pass the absolute path directly to the read tool. If you don't know which tags exist, call kb_list_available_tags first.\n\nThis is a convenience shortcut for multi-dimensional retrieval, NOT the only path. You can also navigate the curated maps under indexes/, or progressively explore the wiki/ tree (read pages, follow [[page-id]] links, grep full text).",
	"kb-list-tags": "List every tag that exists in the knowledge base, each with the number of wiki pages carrying it (orphaned pages excluded), sorted by page count.\n\nUse this to discover the available tag vocabulary before calling kb_filter_by_tags — it keeps your tag filters grounded in tags that actually exist instead of guessing. Takes no arguments.",
	"kb-write-page": "Write (create or update) a single wiki page in the LLM knowledge base at ~/.vetta/knowledges/.\n\nThis is the ONLY way to write wiki pages. It enforces the closed frontmatter schema (exactly: id, source, source_path, source_hash, tags, title, summary, created_at, updated_at, orphaned_at), assigns a stable page id, and refreshes the tags.json / manifest.json caches automatically. Do not hand-write wiki .md files with the generic write tool.\n\nUpsert semantics:\n- Provide `id` to update an existing page in place. The page keeps its id and created_at; updated_at is refreshed. Use this when reprocessing a changed source file (the poller resolves the old id for you).\n- Omit `id`: if a page with the same `source_hash` already exists it is updated; otherwise a new page is created with a freshly assigned id.\n\nTree placement: `path` is relative to wiki/ and you choose it by topic/semantics (e.g. \"产品/计费.md\"), not by mirroring the raws layout. Updating an existing page with a different `path` moves it within the wiki tree (old file removed).\n\nCross-page references: put them in the body as [[page-id]] — never in frontmatter.\n\nraw↔wiki is 1:1. One source raw file maps to exactly one wiki page.",
	"ls": "List directory contents. Returns entries sorted alphabetically, with '/' suffix for directories. Includes dotfiles. Output is truncated to 500 entries or 30KB (whichever is hit first).\n\nALWAYS use this tool to list directory contents. NEVER use bash ls — this tool provides consistent output formatting.\n\nWhen to use `ls` vs other tools:\n- Use `ls` to list immediate contents of a single directory\n- Use `dir_tree` to visualize nested directory structure with hierarchy and counts\n- Use `find` to search for files by name pattern across directories\n- Use `grep` to search for text inside files",
	"memory": "Save or update durable, cross-session memory in MEMORY.md.\n\nMEMORY.md is frozen into your system prompt at the start of each session. It is how you remember things across separate conversations: who the user is, their preferences and environment, the ongoing projects and goals, important decisions, and lessons learned. Without it, every new session starts from zero.\n\nActions:\n- add — append a new memory entry. Provide `content` (one self-contained fact per entry).\n- replace — swap an existing entry. Provide `match` (a substring identifying the entry) and `content` (the new text).\n- remove — delete an entry. Provide `match`.\n\nWhen to save: durable facts and decisions that future sessions should know — not transient chatter, not things already obvious from the files. Prefer a few high-signal entries over many noisy ones.\n\nImportant:\n- Writes are persisted to disk immediately and this tool returns the updated state, so you can see your own writes this turn.\n- But the system-prompt snapshot does NOT change mid-session — your edits re-enter the prompt only on the next session. This is intentional (it preserves the prompt cache).\n- There is a character budget. If a write would exceed it, the tool errors and you must remove or shorten an entry first. Keep memory curated and concise.",
	"progress": "Announce what you are about to do next, so the user sees readable stages instead of raw tool calls.\n\nThe user you are talking to is NOT a developer. They should never have to read a wall of file\nreads, greps and shell commands. Instead, they see a short list of stages you narrate with this\ntool, each collapsing all the tool calls you made inside it.\n\nHow stages work (sliding window):\n- One call does two things at once: `summary` closes and re-titles the stage you just finished,\n  `label` opens the new stage you are starting now.\n- Every tool call you make after a `progress` call belongs to that stage until the next\n  `progress` call.\n- Your final answer text implicitly closes the last stage, so you do not need a trailing\n  `progress` call just to close it.\n\nWorkflow:\n1. Call progress(label=\"…\") BEFORE your first tool call of a task.\n2. Do the work: read, search, extract, convert, whatever the stage needs.\n3. When you move to a genuinely different stage, call\n   progress(summary=\"<what the finished stage achieved>\", label=\"<what you start now>\").\n4. Write the final answer. Do not call progress again afterwards.\n\nWriting good titles:\n- Write in the user's language. Keep each under 40 characters.\n- `label` is present tense, what you are doing: \"Reviewing the quarterly expense sheets\".\n- `summary` is past tense, what came out of it: \"Reviewed 5 expense sheets\".\n- Describe the goal in the user's terms, not the mechanism. Say \"Collecting last quarter's\n  figures\", not \"Running grep and read\".\n- Do not number the stages. Do not repeat the same title twice in a row.\n\nWhen to open a new stage:\n- Open one whenever the purpose of your work changes, even if the tools are the same.\n- 2 to 5 stages is typical for a real task. Do not open a stage per tool call.\n- For a single trivial lookup answered in one tool call, skip this tool entirely.\n\nImportant:\n- Tool calls that produce something the user must see (writing a file, generating a document,\n  an image or a PDF, sending an attachment) should NOT be buried inside a stage. Close the\n  current stage first, produce the artifact, then open the next stage if there is more work.\n- This tool has no side effects and returns nothing useful. It exists purely so the user can\n  follow along.",
	"read": "Read the contents of a file. Supports text files and images (jpg, png, gif, webp). Images are sent as attachments. For text files, output is truncated to 2000 lines or 30KB (whichever is hit first). Use offset/limit for large files. When you need the full file, continue with offset until complete.\n\nText output lines carry an anchor prefix `line:hash→content` (e.g. `42:h7x2→const x = 1;`). The WHOLE `42:h7x2` part is an ANCHOR for the `edit` tool's anchor mode (line number included — never pass the hash alone) — it is metadata, NOT file content. Never treat the prefix as part of the file; when quoting file content to the user, strip the prefix.\n\nCRITICAL: ALWAYS use this tool to read files. NEVER use bash commands (cat, head, tail, less, more, sed -n) to read file contents.\n\nCRITICAL: You MUST read a file with this tool BEFORE editing it with `edit`. Never guess or assume file contents.\n\nWhen NOT to use this tool:\n- Do NOT use for binary document files (.docx, .doc, .xlsx, .xls, .pptx, .ppt, .odt, .ods, .odp). These cannot be read as text. Use `invoke_skill` with the matching skill name (e.g., .docx/.doc → invoke_skill(name=\"docx\"), .xlsx/.xls → invoke_skill(name=\"xlsx\")).\n- For PDFs, pick by intent:\n    · need the text content → `extract_text_from_pdf`\n    · need to LOOK at a page (seals/stamps/盖章, signatures, handwriting, layout, logos, figures) → `render_pdf_page` to get a PNG, then call `read` on the returned PNG path\n    · need to manipulate the PDF (merge/split/rotate/watermark/fill form) → `invoke_skill(name=\"pdf\")`\n- Do NOT use for searching file contents — use `grep` instead.\n- Do NOT use for listing directory contents — use `ls` or `dir_tree` instead.",
	"render-pdf-page": "Render a single PDF page to a PNG image, then return the PNG file path. Use this when you need to LOOK at a PDF page with a vision-capable model, not when you need its text.\n\nAfter this tool returns, follow up with `read(<png_path>)` so the image is loaded as an attachment for visual analysis.\n\nWhen to use (visual judgments OCR cannot make)\n  - Detect official seals / stamps / company chops (盖章 / 印章 / 公章 / 骑缝章)\n  - Detect signatures / initials / handwritten marks\n  - Inspect layout, page structure, header/footer, watermarks\n  - Inspect logos, figures, charts, photographs, color\n  - Read handwriting, stylized fonts, or content the text layer / OCR can't represent\n\nWhen NOT to use\n  - You only need textual content of the page — use `extract_text_from_pdf` (faster, structured).\n  - You want to manipulate the PDF itself (merge / split / rotate / watermark / fill form) — use `invoke_skill(name=\"pdf\")`.\n  - Source is already an image file (.png/.jpg/...) — use `read` directly.\n\nInput\n  - input: path to the source PDF file.\n  - page: 1-based page number to render. Single page only — call again for additional pages so each visual inspection is a deliberate choice.\n  - output (optional): path to write the PNG. Default: <input>.p<page>.png next to the source.\n  - dpi (optional): render DPI. 72-600. Default 200. Lower if the file is huge; higher if you need to read small print or fine seal detail.\n\nOutput (text returned to the agent)\n  A short confirmation block ending with the absolute PNG path, plus an explicit reminder to call `read` on that path next.\n\nRequires `pdftoppm` (poppler) on PATH.",
	"shell": "Execute a shell command in the current working directory. Returns stdout and stderr. Output is truncated to last 2000 lines or 50KB (whichever is hit first). If truncated, full output is saved to a temp file. Optionally provide a timeout in seconds.\n\n# Foreground vs background (CRITICAL)\n\nDefault is FOREGROUND: the agent is BLOCKED until the command exits (or until the soft wait, then auto-promote — see Modes).\n\nNEVER run a process that does not exit on its own in the foreground without `run_in_background: true`.\n\nMUST set `run_in_background: true` for anything that keeps the console open / runs until killed, including:\n- Dev servers: npm/pnpm/yarn/bun run dev|start, vite, next dev, nuxt, webpack-dev-server\n- Watchers: *--watch*, nodemon, vitest --watch, jest --watch\n- Containers: docker compose up (without -d), docker run (without -d)\n- Make/scripts that serve: make dev, make serve, rails s, flask run, uvicorn (no oneshot)\n- Tunnels / REPL / follow: ssh -N, tail -f, python -i\n\nDecision:\n- Will this process exit on its own within about a minute? → foreground (optional hard `timeout`)\n- Will it keep running until killed? → `run_in_background: true`\n- Unsure? → `run_in_background: true`\n\nDo NOT use shell `&`, `nohup`, or manual disown; use `run_in_background`.\nDo NOT poll with long `sleep` while waiting on a foreground server — that hangs the agent.\n\n# Modes\n\n1. `run_in_background: true` — starts immediately as a background task; returns task ID. Use `task_output` / `task_stop`. When the command finishes you receive a `<task-notification>`. Ignores timeout.\n2. `timeout: N` — foreground with hard kill after N seconds (bounded work: builds, one-shot tests).\n3. Neither set — foreground soft wait (default 45s). If still running, auto-promoted to a background task (same as background after the wait). Quick commands still return inline when they exit before the soft wait.\n\nDo NOT use `run_in_background` for quick one-shot commands — the result arrives faster inline.\n\nIMPORTANT: NEVER use shell for operations that have dedicated tools. Use the right tool:\n- File reading: ALWAYS use `read` (NEVER cat, head, tail, less, more)\n- File editing: ALWAYS use `edit` (NEVER sed, awk, perl -i)\n- File writing: ALWAYS use `write` (NEVER echo >, cat <<EOF, tee)\n- File search by name: ALWAYS use `find` (NEVER shell find, fd, locate)\n- File content search: ALWAYS use `grep` (NEVER shell grep, rg, ag, ack)\n- Directory listing: ALWAYS use `ls` or `dir_tree` (NEVER shell ls, tree)\n- PDF text extraction: ALWAYS use `extract_text_from_pdf` (NEVER pdftotext, pdf2txt, pdfinfo)\n- Image text extraction: ALWAYS use `extract_text_from_img` (NEVER tesseract, ocrmypdf)\n- Skill invocation: ALWAYS use `invoke_skill` (NEVER shell find/locate/mdfind to search for skill files)\n\nUse shell ONLY for: running scripts, package managers (npm, pip, cargo, etc.), git commands, compilers, interpreters, complex piping, or commands with no dedicated tool equivalent.\n\n# Skill / Scene Directory Protection\n\nSkill and scene directories are READ-ONLY. NEVER write output files, temp files, logs, or any generated content into skill or scene directories.\n\nProtected paths (NEVER write here):\n- ~/.vetta/agent/skills/ and its subdirectories\n- ~/.vetta/skills/ and its subdirectories\n- ~/.vetta/scenes/ and its subdirectories\n- .vetta/skills/ under the current project\n\nWhen a skill or scene needs to produce output files (e.g. generated PDFs, images, reports), ALWAYS write them to the user's working directory (cwd) or a subdirectory thereof. For example, write to `./output.pdf` instead of placing the file inside the skill folder.\n\n# Git Safety Protocol\n\nWhen running git commands, follow these rules strictly:\n- NEVER run destructive git commands without explicit user request:\n  - `git reset --hard` - destroys uncommitted changes\n  - `git push --force` / `git push -f` - can overwrite remote history\n  - `git checkout .` / `git restore .` - discards all local changes\n  - `git clean -fd` - deletes untracked files permanently\n  - `git branch -D` - force-deletes a branch\n  - `git stash drop` - permanently discards stashed changes\n- NEVER skip hooks: do NOT use `--no-verify` or `--no-gpg-sign` unless user explicitly asks\n- NEVER use `git add -A` or `git add .` - these can stage unrelated files. ALWAYS add specific files by path\n- NEVER amend commits unless user explicitly requests it - amending can destroy the previous commit\n- Before any destructive operation, consider if there is a safer alternative\n\nOn Windows, this tool uses PowerShell by default.\n\n注意：对用户可见的输出文案禁止硬编码中文，统一走 i18n。",
	"todo": "Manage a todo list to plan and track progress on multi-step tasks.\n\nWhen to create a todo plan:\n- Task requires 3 or more distinct steps\n- User asks to modify multiple files\n- Task involves sequential work (step A must finish before step B)\n- User explicitly asks for a plan (\"plan\", \"todo\", \"step by step\", \"分步\", \"计划\", \"列个清单\")\n\nWhen NOT to create:\n- Single file edit or simple question\n- Task completable in 1-2 trivial steps\n- Purely informational or conversational request\n\nWorkflow:\n1. If a todo list may already exist, call todo(action=\"list\") before creating a new plan.\n2. Call todo(action=\"create\") with all planned steps BEFORE starting any work, but only when the list is empty.\n3. Call todo(action=\"update\", id=N, status=\"in_progress\") when you START a step.\n4. Call todo(action=\"update\", id=N, status=\"done\") when you FINISH a step.\n5. Update status in real time — do not batch updates.\n6. Prefer completing items in order, but you MAY reprioritize or update out of order when it makes sense.\n7. If the user changes direction and the current plan no longer applies, call todo(action=\"clear\") to abandon it, then create a fresh plan.\n\nNever call create to start a new plan when a todo list already exists. Create does not append a new plan to an existing plan: it will be rejected. First call list, then either continue the existing plan or clear it if obsolete.\n\nAim to finish the items you committed to — don't abandon a plan halfway without reason. If the user has redirected you, clear the stale plan rather than ignoring it.\n\nNOTE — locked lists are STRICT: lists created from a scene's tasks.json are locked. For a locked list you MUST complete items in strict sequential order by ID, you CANNOT create or clear items, and you MUST finish every item before stopping. Out-of-order updates and clear are REJECTED, and the system will force you to continue if you stop early.",
	"tool-search": "Search the deferred MCP tool index by keyword and activate matching tools.\n\nWhen many MCP tools are configured, most are not loaded into your tool list up front — only an index of names and one-line descriptions appears in the system prompt. Call this tool with keywords (tool name fragments, server name, or capability words like \"page\", \"database\", \"issue\") to activate the best matches; their full schemas are added to your tool list immediately and are callable on your very next step.\n\nGuidance:\n- Prefer keywords copied from the MCP tool index in the system prompt.\n- When the user names a specific MCP server or tool, search for that name.\n- Once a tool is reported as activated or already active, call that tool directly. Never re-run tool_search for the same tool — repeated searching makes no progress.\n- Activation persists for the rest of the session; there is no need to re-search for tools already activated.\n- If nothing matches, retry with broader or different keywords before telling the user the capability is unavailable.",
	"tree": "Render a compact directory tree for a path, with explicit node types and counts:\n- [D] for directories (with immediate child counts: d:<dirs>, f:<files>)\n- [F] for files\n- Each rendered node also includes a stable path ID like `id=@PATH_0001`\n\nALWAYS use this tool (not bash `tree` or `find`) when you need a directory structure overview.\nUse path IDs directly as tool path arguments to avoid filename mutation by the model.\n\nWhen to use `dir_tree` vs other tools:\n- Use `dir_tree` FIRST when you need a high-level map of a codebase with minimal token usage, then drill down with `read`/`find`/`grep`\n- Use `ls` for simple flat listing of one directory\n- Use `find` to search for specific file name patterns\n- NEVER use bash commands (tree, find, ls -R) for directory structure — always use this tool\n\nPerformance and safety:\n- Uses fd for fast cross-platform scanning (macOS/Linux/Windows)\n- Respects .gitignore by default\n- Supports maxDepth and node limits to avoid context explosion\n- Truncates output when size limits are hit",
	"write": "Write content to a file. Creates the file if it doesn't exist, overwrites if it does. Automatically creates parent directories.\n\nWhen to use `write` vs `edit`:\n- Use `write` ONLY for creating NEW files or COMPLETE rewrites where most of the content changes.\n- For modifying specific parts of an existing file, ALWAYS prefer `edit` — it is more precise and less error-prone.\n- NEVER use bash commands (echo >, cat <<EOF, tee, printf >) to write files — always use this tool or `edit`.\n\nCRITICAL: If overwriting an existing file, you MUST read it first with `read` to understand its current contents. Do NOT blindly overwrite files without reading them."
};
